// Typed access to the projected AI Architect catalog (data/studio-catalog.json).
// The JSON is generated by scripts/sync-studio.mjs; nothing here invents data.

export type LayerId = 'people' | 'control' | 'intelligence' | 'knowledge' | 'assurance'
export type FlowKind = 'data' | 'control' | 'telemetry'
export type Actor = 'customer' | 'agent' | 'system' | 'reviewer' | 'operator'

