  economics: Economics
  components: Component[]
  flows: Flow[]
  journey: JourneyStep[]
  team: TeamStep[]
  screens: Screen[]
  evals: { id: string; name: string; threshold: string; method: string }[]
  risks: { id: string; risk: string; control: string }[]
  realizations: Record<string, Realization>
